nary '{\"jsonmodel_type\":\"note_langmaterial\",\"type\":\"langmaterial\",\"content\":[\"English.\"],\"persistent_id\":\"4384c0aa18fea2689f6740e189543e10\"}','admin','admin','2022-04-03 17:34:53','2022-04-03 17:34:53','2022-04-03 17:34:53',NULL,NULL,252,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(174,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_langmaterial\",\"type\":\"langmaterial\",\"content\":[\"English.\"],\"persistent_id\":\"3db771ff17abab01a52ff009f113e0fb\"}','admin','admin','2022-04-03 17:34:53','2022-04-03 17:34:53','2022-04-03 17:34:53',NULL,NULL,254,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(199,1,NULL,170,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"This series consists of various scripts, one budget, and one production schedule for movies produced from 1927 to 1995. Along with final scripts, this series also contains drafts at different stages and scripts for films that were never made such as Brigade West, Sweet Savage Love, and Tom Sawyer, 1967.\",\"subnote_guid\":\"55c62841b04a430e0e69473a8c84d06a\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_e62fa5f1666f31fd3ed63b93fbd53f5e\",\"label\":\"Scope and Contents note\"}','admin','admin','2022-04-03 17:44:19','2022-04-03 17:44:19','2022-04-03 17:44:19',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(200,1,NULL,170,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Arranged chronologically.\",\"subnote_guid\":\"5d278494c075c3f80865d31ba3b35924\"}],\"type\":\"arrangement\",\"persistent_id\":\"aspace_35888af42a55e2a29b6ac79df01a24d7\",\"label\":\"Arrangement note\"}','admin','admin','2022-04-03 17:44:19','2022-04-03 17:44:19','2022-04-03 17:44:19',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(201,1,NULL,171,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"This series contains promotional material related to films produced between 1937 to 1981. Promotional material consists of television publicity kits, study booklets, press books and releases, press clippings, photographs and other material related to the promotion of films. Folders 160-162 contain materials associated with Windwalker\'s campaign to be included in the Academy Awards.\",\"subnote_guid\":\"cd02c48122a5baaebc434f0fe18de78c\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_9d5386c9a5426a157133ae1f17f20f33\",\"label\":\"Scope and Contents note\"}','admin','admin','2022-04-03 17:44:19','2022-04-03 17:44:19','2022-04-03 17:44:19',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(202,1,NULL,171,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Arranged chronologically.\",\"subnote_guid\":\"77f76dcb8c69e9ea89617c33167a3c71\"}],\"type\":\"arrangement\",\"persistent_id\":\"aspace_a2c255ee2aaac73804a96af04cc15676\",\"label\":\"Arrangement note\"}','admin','admin','2022-04-03 17:44:20','2022-04-03 17:44:20','2022-04-03 17:44:20',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(203,1,NULL,172,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"This series contains lobby cards for films produced between 1940 to 1978.\",\"subnote_guid\":\"639f898335d6e3426f6b4f213b429170\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_342846e964ac287f435ebe76eaaa8c7c\",\"label\":\"Scope and Contents note\"}','admin','admin','2022-04-03 17:44:20','2022-04-03 17:44:20','2022-04-03 17:44:20',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(204,1,NULL,172,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Arranged chronologically.\",\"subnote_guid\":\"db42ce1747d01f6cfc36125364cfa715\"}],\"type\":\"arrangement\",\"persistent_id\":\"aspace_f7543b55735671963095fa13cf8a47fe\",\"label\":\"Arrangement note\"}','admin','admin','2022-04-03 17:44:20','2022-04-03 17:44:20','2022-04-03 17:44:20',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(205,1,NULL,173,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"This series consists of photographic film stills for movies produced between 1936 to 1968. Also includes 307 Polaroid photographs of Native American extras for the 1990 film \\\"Dances With Wolves.\\\" Most Polaroids are of hair and makeup.\",\"subnote_guid\":\"78d8db44566041229fdbece521d85c7b\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_8c7cfa243c52e1fadcdec84392d3641d\",\"label\":\"Scope and Contents note\"}','admin','admin','2022-04-03 17:44:20','2022-04-03 17:44:20','2022-04-03 17:44:20',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(206,1,NULL,173,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Arranged chronologically.\",\"subnote_guid\":\"f6c204c2efd893d402d616adab92d15e\"}],\"type\":\"arrangement\",\"persistent_id\":\"aspace_49f8e8d62b52f951ce25e041563bfa66\",\"label\":\"Arrangement note\"}','admin','admin','2022-04-03 17:44:20','2022-04-03 17:44:20','2022-04-03 17:44:20',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(207,1,NULL,174,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"This series consists of oversized promotional materials related to movies produced between 1936 to 1980 such as press books.\",\"subnote_guid\":\"b1ac79fc3641ea559fa718089ecb0c37\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_9864cb2e6e3985594977fd39aa622fa8\",\"label\":\"Scope and Contents note\"}','admin','admin','2022-04-03 17:44:20','2022-04-03 17:44:20','2022-04-03 17:44:20',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(208,1,NULL,174,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Arranged chronologically.\",\"subnote_guid\":\"3b71b4f3cbe66511d5c9e840a2fca03a\"}],\"type\":\"arrangement\",\"persistent_id\":\"aspace_43f9d6b6b498bcc05f2f70da8aa06c15\",\"label\":\"Arrangement note\"}','admin','admin','2022-04-03 17:44:20','2022-04-03 17:44:20','2022-04-03 17:44:20',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(209,1,NULL,175,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"This series consists of oversized film posters from films produced between 1912 to 2018. See oversize flat file for Folder 1.\",\"subnote_guid\":\"9abd2de94d76d9956bf1b61c0ad4072b\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_b3bad052fb5a66a88386c06fdf8b505d\",\"label\":\"Scope and Contents note\"}','admin','admin','2022-04-03 17:44:20','2022-04-03 17:44:20','2022-04-03 17:44:20',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(210,1,NULL,175,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Arranged by size and then chronological order.\",\"subnote_guid\":\"73a6259f0a9bfb417860ed5fdf5da13d\"}],\"type\":\"arrangement\",\"persistent_id\":\"aspace_c346398ac86114d1777632c1bae46f0b\",\"label\":\"Arrangement note\"}','admin','admin','2022-04-03 17:44:20','2022-04-03 17:44:20','2022-04-03 17:44:20',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(243,1,NULL,448,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"This series primarily consists of materials related to Arai and Wong\'s involvement in the Asian American Movement, particularly their engagement with grassroots and arts-related organizations and institutions. Many of these organizations were small Asian American artist-driven organizations within New York, representing the needs and interests of this community during the 1970s and 1980s. \\n\\n \\n\\n This series includes files on the Cityarts Workshop, a nonprofit community mural arts organization in the 1970s that created murals by and for communities of color. Arai\'s artwork was used heavily for the organization\'s publications and posters during her time with them. Files include promotional material, press clippings, correspondence, presentations, mural planning notes, newsletters, original sketches by artists, and photographs of events, artwork, and artists working on murals. This series also includes publications and leaflets used as inspiration for graphics and murals. \\n\\n \\n\\n In the 1970s, Arai and Wong both worked for the Basement Workshop, which was one of the first Asian-American political, community, and arts organizations in New York City. This series contains files on projects produced by this organization, including proofs for the record album <emph render=\\\"italic\\\"> A Grain of Sand: Music for the Struggle by Asians in America</emph> and production files for the publication <emph render=\\\"italic\\\">Yellow Pearl</emph>. Organizational records also contain photographs, promotional material, event announcements, and member lists. Many of the printed items contain Arai\'s artwork. \\n\\n \\n\\n This series also contains meeting notes, letterhead, event announcements, member lists, correspondence, historic timelines, and newsletters for the Godzilla Asian American Arts Network, a New York-based Asian American arts collective and support network in the 1990s, of which Arai was a founding member. Planning files on the exhibition <emph render=\\\"italic\\\">A New World Order</emph> are in this series, as well as a Godzilla award figurine, two graphic hats, a t-shirt, newsletters, and a video recording containing interviews with Godzilla members. \\n\\n \\n\\n Other New York organizations with files in this series are the Museum of Chinese in the Americas (previously the New York Chinatown History Project), New York Asian Women\'s Center, United Asian Communities Center, Asian American Arts Alliance, and Chinatown Health Clinic. These files typically include event invitations and programs, informational brochures and booklets, posters, and correspondence. There is also a small collection of buttons in this series, documenting various Asian political causes and arts groups.\",\"subnote_guid\":\"cf5638d368576ef0422b998c47e6f9b4\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_4c77258f90d9bdee2b06a631b6f832fc\",\"label\":\"Scope and Contents\"}','admin','admin','2022-04-03 18:03:04','2022-04-03 18:03:04','2022-04-03 18:03:04',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(244,1,NULL,449,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"This series contains materials created and accumulated by Arai on the research, production, and exhibition of her artwork, as well as her involvement in the Asian American arts community in New York. The overlap in her artwork and activism is often apparent in the art theme, her projects, and where the works are shown. \\n\\n \\n\\n Arai\'s large collection of exhibition catalogues and ephemera by Asian artists in this series spans the 1970s to the 2000s and not only shows artists active during this timeframe but also the themes that were popular during various decades, as well as which New York galleries and museums were representing and showing their work. \\n\\n \\n\\n This series also contains a comprehensive collection of Arai\'s own exhibition catalogues, announcements, fliers, and related correspondence dating from 1970 to 2000s which shows the volume of projects she was involved with from year to year. The correspondence especially illustrates the work involved to promote herself and her art, apply for funding, plan exhibitions, loan out artworks, and network with galleries and institutions. Projects of note include <emph render=\\\"italic\\\">Double Happiness</emph> and <emph render=\\\"italic\\\"> Mi Familia Mi Comunidad</emph> and <emph render=\\\"italic\\\">Renewal</emph>, which was commissioned for the African Burial Ground National Monument. \\n\\n \\n\\n Work files, publications, and posters related to Arai\'s printmaking and illustration work date from the 1970s to the 1990s, mostly for local New York organizations including Cityarts, Basement Workshop, and Chinatown Health Clinic. These posters are often multi-lingual, depending on the organization. Publications containing Arai\'s work include <emph render=\\\"italic\\\">Heresies</emph>, <emph render=\\\"italic\\\">Upfront</emph>, and <emph render=\\\"italic\\\">East Village Review</emph>. Arai also illustrated a children\'s book <emph render=\\\"italic\\\">China\'s Bravest Girl</emph>, and this series contains correspondence, reviews, promotional material as well as the book. \\n\\n \\n\\n Throughout her career, Arai was the recipient of many residencies and fellowships to fund the progress of her art and related projects. This series includes files for Goddard-Riverside Community Center, New York Foundation for the Arts (NYFA), MoMA PS 1, MacDowell Colony, and Cummington Artist Colony and usually contain correspondence, applications, project reports, and event announcements. Material related to her 1998 Artist in Residency with the New York University Asian/Pacific/American Institute are also in this series.\",\"subnote_guid\":\"08537b069cdccf78b0116054566cf69c\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_d953c5b46fff37fc4602afab06532705\",\"label\":\"Scope and Contents\"}','admin','admin','2022-04-03 18:03:04','2022-04-03 18:03:04','2022-04-03 18:03:04',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(245,1,NULL,450,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"This series includes material on Legan Wong\'s work on development of Asian American Studies classes, music production, and his involvement in activist and local cultural organizations in New York in the 1970s and 1980s. \\n\\n \\n\\n This series contains source material, lecture notes, course outlines, and correspondence related to Wong\'s development of college classes on the Asian American experience that he created and taught at Queens College and Hunter College in the 1970s. General research files and conference material on Asian American Studies are also in this series. \\n\\n \\n\\n Wong was involved in performance groups in the 1970s and 1980s including Soh Daiko, a folk music drum group, and the Asian Tactical Theater. These files typically include performance programs and schedules, financial reports, promotional material, news clippings, correspondence, notes, and meeting minutes. Wong was also on Team Ronin in the Asian American Softball League of New York in the late 1970s. Team material in this series includes member identification cards with photographs, schedules, correspondence, and rosters. \\n\\n \\n\\n This series contains a small amount of files on Wong\'s involvement in the 1980s as a founding member of East West World Records, which was founded to provide recording opportunities for Asian American artists. These files include concert promotional material, news clippings, letterhead, financial funding, and founding documentation. This series also includes two of the record albums the company produced: <emph render=\\\"italic\\\">Visions</emph>, and <emph render=\\\"italic\\\">Back to Back</emph>. \\n\\n \\n\\n Newsclippings, newsletters, and promotional material for various political groups in which Wong was involved include the Asian Americans for Equal Employment (AAFEE) and Asian in the Spirit of the Indochinese (ASI) are also in this series.\",\"subnote_guid\":\"ab7fab6960c71a77348c4101f9bd4804\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_0a5dc8a5085c9219213ab4043edbf181\",\"label\":\"Scope and Contents\"}','admin','admin','2022-04-03 18:03:04','2022-04-03 18:03:04','2022-04-03 18:03:04',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(246,1,NULL,451,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"This series contains materials documenting Arai\'s early adult life, as well as items created and collected by other family members including her parents, Tim and Tomoe, and her uncle. Arai\'s school awards, class photographs, and newsletters containing Arai illustrations are mostly from Booker T. Washington Junior High School. Later 1960s photographs of Arai as a young activist are also in this series. \\n\\n \\n\\n Record albums from Tim and Tomoe\'s personal collection in this series include a 1937 Billie Holiday album, a signed copy of the soundtrack for the Broadway show, <emph render=\\\"italic\\\">Flower Drum Song</emph>, and Asian American Broadway performer Pat Suzuki\'s signed album. A history and correspondence related to the New York Buddhist Church in this series relates to the life-long involvement of Arai and her parents in this church community, which also includes photographs from the 1950s of a Bon Odori Festival in Riverside Park. Other items collected by Tim and Tomoe include a print portfolio and newsletters of the Nisei Progressives from the 1950s, publications related to Tim\'s publication editorial work in the 1940s and 1970s, including a program that also includes Tomie Arai\'s artwork on the cover. \\n\\n \\n\\n Material collected from Arai\'s parents also include items specifically related to the Japanese American experience during and following World War II in the United States. Items include two Japanese American \\\"yearbook\\\" directories from 1948 and 1949, printed in Japanese and English, one for New York and the other for the entire United States. These directories listed addresses for Japanese individuals which included Tim and Tomoe, and Asian-owned companies. A master\'s thesis including an interview with Tomoe Arai related to college women and Japanese American wartime incarceration is in this series. Other materials collected by Tomoe Arai include general informational booklets, publications, and articles on the incarceration of Japanese Americans with some specifically related to Tule Lake War Relocation Center and the Granada Relocation Center (also known as Camp Amache), concentration camps in California and Colorado, respectively. Also of note in this series are 15 original watercolor paintings of the Topaz Relcation Center by Arai\'s paternal uncle, Unosuke Sasahi, which were created during 1943 to 1944 during his incarceration. A 1943 informational booklet on the Granada Relocation Center in Amache, Colorado was given to Tomie Arai\'s grandparents when they were transferred from the Tule Lake War Relocation Center. Promotional material and schedules from a 1991 pilgrimage event to Tule Lake National Park are also in this series\",\"subnote_guid\":\"94d78c487c31b8858d42f85cdcf8524a\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_e6909f68182643507ba341b32715d798\",\"label\":\"Scope and Contents\"}','admin','admin','2022-04-03 18:03:04','2022-04-03 18:03:04','2022-04-03 18:03:04',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(259,1,NULL,571,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"The files contained in this series document Shimanouchi-Lederer\'s personal life. Materials include legal and personal documents, unpublished book transcripts, personal correspondence, research articles, and newspaper clippings. Included in the family history files are media clippings, pamphlets belonging to Shizue Shimanouchi, and writings of Henry Toshio Shimanouchi, former General Consul of Japan. The bulk of materials are photo albums covering family history during their settlement in Los Angeles and San Francisco, California (1890-1970). Of significance are Shimanouchi-Lederer\'s NARA files that document her family\'s forced removal and incarceration at the Topaz Relocation Center, with government records and her application to the War Relocation Authority for leave of clearance to pursue a university education. This series also includes extensive oral history transcripts her childhood struggles where Lederer describes her childhood struggles growing up as a Japanese American during the pre-WW II era, her marriages, incarceration experience, career rise in the Hollywood publicity circuit, and grassroots organizing to create JASSI. Also of note are copies of scholarly publications and news articles that integrate Shimanouchi-Lederer\'s interviews on her incarceration experience.\",\"subnote_guid\":\"729b2ca18852ccb737098e07f6a68fdc\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_eb9561cb4cef9037b3df020f29230d3f\",\"label\":\"Scope and Contents\"}','admin','admin','2022-04-03 18:03:47','2022-04-03 18:03:47','2022-04-03 18:03:47',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(260,1,NULL,572,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"Files within this series relate to Shimanouchi-Lederer\'s professional career as a manager and secretary for Mike Todd Company, a press agent for Bill Doll Company, and her tenure as director of JASSI. The bulk of materials within the series are photographs, some of which are retained in the original order of the albums. Photographs from her Michael Todd days document Shimanouchi alongside Michael Todd and former wife, Elizabeth Taylor, in private settings with other celebrities, as well as at other large red carpet events and venues. Papers from her time at the Michael Todd Company include various newspaper and media clippings, correspondence, press releases.\\n\\nThe Bill Doll and Company files are mainly comprised of photos, many of which were used for press releases and captured Shimanouchi with famed actors, directors and producers of the 1950s - 1960s. While a large folder of photos from Shimanouchi\'s publicity days remain unidentified, they offer a glimpse into the publicity networks with which Shimanouchi was affiliated. \\n\\nContents within the JASSI files document programming and events, organizational publications, newsletters, flyers and some correspondence. Writings by former JASSI volunteers and staff members provide contextual community history of JASSI. The bulk of JASSI materials are photo albums documenting various JASSI fundraising events and former staff members of the organization.\",\"subnote_guid\":\"8788bea1c0ababbeb572a3e456b8f11e\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_af3226ae95fe16cfab7d9edb84480559\",\"label\":\"Scope and Content Note\"}','admin','admin','2022-04-03 18:03:47','2022-04-03 18:03:47','2022-04-03 18:03:47',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(261,1,NULL,573,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"This series contains cassette tapes documenting the oral history of Shimanouchi-Lederer during her early childhood days, her family\'s forced removal and incarceration during World War II, and her professional career as a manager for a Hollywood production company, press agent, and as founding director of JASSI. The transcripts accompanying the audio tapes are part of Series I. \\n\\nThe videos are recordings of broadcasts that include Shimanouchi-Lederer on academic panels discussing Social Justice for Asian Americans, and a Japanese televised special on her brother, Henry Toshiro Shimanouchi. Other recordings document JASSI fundraising concerts held in the early 1990s.\",\"subnote_guid\":\"1d12372bd609d9966b7150eb4883f259\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_06882ffb390497cf26a161559ca1532a\",\"label\":\"Scope and Content Note\"}','admin','admin','2022-04-03 18:03:47','2022-04-03 18:03:47','2022-04-03 18:03:47',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(273,1,NULL,629,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"These files are closed to researchers for 75 years from the end date within each folder.\",\"subnote_guid\":\"ff31c7dd4cc3b5840d8be6651493d2be\"}],\"type\":\"accessrestrict\",\"persistent_id\":\"aspace_a9bc66901c3e72b1b8d6e71095ae88ec\",\"label\":\"Conditions Governing Access\"}','admin','admin','2022-04-03 18:04:22','2022-04-03 18:04:22','2022-04-03 18:04:22',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(292,1,NULL,662,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"This series is arranged chronologically.\",\"subnote_guid\":\"f9ce92477e96c2e44a6f117cb6ceefe3\"}],\"type\":\"arrangement\",\"persistent_id\":\"aspace_47608275c7cc2eb987e7ce4e6fa574be\",\"label\":\"Arrangement\"}','admin','admin','2022-04-03 18:04:55','2022-04-03 18:04:55','2022-04-03 18:04:55',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(293,1,NULL,662,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"The Activism series consists of materials documenting Rocky Chin\'s organizing and professional work with the New York City Commission on Human Rights, as well as the cultural events, strikes, and demonstrations in which he was involved. Materials include newsletters, correspondence, memos, meeting minutes, conference programs, brochures, booklets, flyers, speeches, T-shirts, posters, demonstration signs, optical discs, and a VHS tape. Of note are the materials documenting the organization and implementation of the first New York City Hall conference roundtable in 1992 addressing the concerns of the city\'s Asian Pacific American communities. These documents include press releases, memos, correspondence, reports, schedules, invitations, speeches, summaries and lists of attendees and issues.\\n\\nA large portion of the Activism series consists of research files which informs Rocky Chin\'s work in his various organizational roles, his work at the New York City Commission on Human Rights, his interests as a professor, and while campaigning. Some of these materials highlight various issues such as employment discrimination, Japanese American World War II incarceration and reparations, language rights, redistricting and rezoning initiatives, the Asian American studies movement, city projects (e.g. Chung Park Project, Foley Square Courthouse Project), the Vincent Chin case, negative media depictions of Asian Americans, among many other subjects. These research files include materials such as periodicals, publications, reports, legal briefs, newspaper clippings, and event and conference programs.\",\"subnote_guid\":\"6b900011234a25b6943e49c9f0af3af5\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_a48ac8f03e85f9aadbce36d472ccc48f\",\"label\":\"Scope and Contents\"}','admin','admin','2022-04-03 18:04:55','2022-04-03 18:04:55','2022-04-03 18:04:55',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(294,1,NULL,663,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"This series is arranged chronologically.\",\"subnote_guid\":\"41e43c728db4eea5063dd630093741d2\"}],\"type\":\"arrangement\",\"persistent_id\":\"aspace_af96bc1e3e5e7094f3177ace72904d0b\",\"label\":\"Arrangement\"}','admin','admin','2022-04-03 18:04:55','2022-04-03 18:04:56','2022-04-03 18:04:55',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(295,1,NULL,663,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"The Political Campaigns series documents Rocky Chin\'s involvement in various New York City elections, including Jesse Jackson\'s presidential campaign in 1988, David Dinkin\'s mayoral campaign in 1989, and Sau Ngar Li and Danny Yip\'s 1999 run for the District 2 Community School Board Elections. Materials include correspondence, memos, press releases, newspaper clippings, statements, flyers, event programs, invitations, mailers, brochures, speeches, schedules, and meeting notes. In addition to these types of materials, Chin\'s own run for city council representative is also documented by completed candidate questionnaires and surveys, printed campaign literature, printouts of digital photographs, a campaign banner, and photographic contact sheets. Rocky Chin was a delegate at the 1996 and 2000 Democratic National Conventions, and supported Barack Obama\'s presidential candidacy in 2008, but the materials he collected from these roles are included in the Activism series, since it does not appear that he had a larger role in the campaigns.\",\"subnote_guid\":\"67e037f02f4dd1fdba1ad90851c6b11e\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_44d778b2c9ba5a8955da187e98450a88\",\"label\":\"Scope and Contents\"}','admin','admin','2022-04-03 18:04:56','2022-04-03 18:04:56','2022-04-03 18:04:56',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(296,1,NULL,664,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"This series is arranged chronologically.\",\"subnote_guid\":\"8e7dc1c365772d96d826910936583dd8\"}],\"type\":\"arrangement\",\"persistent_id\":\"aspace_5cb4a74bac5fba47bc512080b5089d94\",\"label\":\"Arrangement\"}','admin','admin','2022-04-03 18:04:56','2022-04-03 18:04:56','2022-04-03 18:04:56',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(297,1,NULL,664,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"The materials in this series were expressly collected to develop course content at Hunter Colleges and the City College of New York, and include legal briefs, articles and readings, and newspaper clippings. This series also contains correspondence, syllabi, flyers, teaching observations, course flyers, and blank exams. Many of the research files he collected in his activism work informs the Asian American studies courses he taught, such as \\\"Asian American Experience: Contemporary Issues,\\\" \\\"US Policy Towards Asia - Asian Americans,\\\" and \\\"Asian Americans Civil Rights and the Law.\\\"\",\"subnote_guid\":\"ef0cdfe1bc339dda11f3678b78cff1a9\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_7fc3b9df942e829713fddddf8acefe9c\",\"label\":\"Scope and Contents\"}','admin','admin','2022-04-03 18:04:56','2022-04-03 18:04:56','2022-04-03 18:04:56',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(306,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_langmaterial\",\"type\":\"langmaterial\",\"persistent_id\":\"aspace_75b33c54e777e001df3aab1ac2f0269f\",\"content\":[\"Interview in English\"]}','admin','admin','2022-04-03 18:09:25','2022-04-03 18:09:25','2022-04-03 18:09:25',NULL,NULL,271,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(307,1,NULL,851,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"[AC1202 - AC1204]\",\"subnote_guid\":\"35df0b84aa31c511ab1a8053e0fbe937\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_4cbf7fe906258df4c7ae3c2a579e78dd\",\"label\":\"Scope and Contents\"}','admin','admin','2022-04-03 18:09:25','2022-04-03 18:09:25','2022-04-03 18:09:25',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(308,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_langmaterial\",\"type\":\"langmaterial\",\"persistent_id\":\"aspace_1c605cc324962b5c0d9b8e1cfd5350ee\",\"content\":[\"Interview in English\"]}','admin','admin','2022-04-03 18:09:25','2022-04-03 18:09:25','2022-04-03 18:09:25',NULL,NULL,272,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(309,1,NULL,852,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"content\":\"[AC1205]\",\"subnote_guid\":\"a8a1dd48a6a3e1eb8adb28e38c122bc0\"}],\"type\":\"scopecontent\",\"persistent_id\":\"aspace_f13811606e977c24c578af57e2ee4a64\",\"label\":\"Scope and Contents\"}','admin','admin','2022-04-03 18:09:25','2022-04-03 18:09:25','2022-04-03 18:09:25',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(310,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_langmaterial\",\"type\":\"langmaterial\",\"persistent_id\":\"aspace_b8d9187b4653763f992e17c7b7bd61ee\",\"content\":[\"Interview in English\"]}','admin','admin','2022-04-03 18:09:25','2022-04-03 18:09:25','2022-04-03 18:09:25',NULL,NULL,273,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(311,1,NULL,853,NULL,NULL,NULL,NULL,NULL,NULL,1,1,_binary '{\"jsonmodel_type\":\"note_multipart\",\"subnotes\":[{\"publish\":true,\"jsonmodel_type\":\"note_text\",\"conte