CREATE TABLE `subject` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `lock_version` int(11) NOT NULL DEFAULT '0',
  `json_schema_version` int(11) NOT NULL,
  `vocab_id` int(11) NOT NULL,
  `title` varchar(8704) DEFAULT NULL,
